package tank;
import java.net.*;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static tank.Protocol.*;
import static org.junit.jupiter.api.Assertions.*;
class FailureTest {
 @TempDir Path tmp;
 Server server()throws Exception{Path cfg=tmp.resolve("server.properties");Files.writeString(cfg,"bind=127.0.0.1\ntcp.port=0\nudp.port=0\nbenchmark=true\nmap.path="+Path.of("../../source/client/Assets/StreamingAssets/map.json").toAbsolutePath().normalize().toString().replace('\\','/')+"\ndatabase.path="+tmp.resolve("db").toString().replace('\\','/')+"\nspool.path="+tmp.resolve("spool").toString().replace('\\','/')+"\nmetrics.path="+tmp.resolve("csv").toString().replace('\\','/')+"\n");Server s=new Server(new Config(cfg));s.start();return s;}
 @Test void invalidHostMigrationDuplicateLoginMalformed()throws Exception{try(Server s=server();Socket a=new Socket("127.0.0.1",s.tcp.getLocalPort());Socket b=new Socket("127.0.0.1",s.tcp.getLocalPort());Socket duplicate=new Socket("127.0.0.1",s.tcp.getLocalPort())){a.setSoTimeout(5000);b.setSoTimeout(5000);duplicate.setSoTimeout(5000);BaselineTest.auth(a,"alpha");BaselineTest.auth(b,"bravo");BaselineTest.send(duplicate,LOGIN,new Writer().str("ALPHA").str("password123").done());assertEquals(Protocol.Error.ALREADY_LOGGED_IN.ordinal(),new Reader(BaselineTest.waitFor(duplicate,LOGIN_RESULT).payload()).u16());BaselineTest.send(a,CREATE_ROOM,new Writer().str("test").done());BaselineTest.waitFor(a,ACTION_RESULT);int room=new Reader(BaselineTest.waitFor(a,ROOM_STATE).payload()).u32();BaselineTest.send(b,JOIN_ROOM,new Writer().u32(room).done());BaselineTest.waitFor(b,ACTION_RESULT);BaselineTest.waitFor(b,ROOM_STATE);BaselineTest.send(b,KICK_PLAYER,new Writer().u8(0).done());assertEquals(Protocol.Error.NOT_HOST.ordinal(),new Reader(BaselineTest.waitFor(b,ACTION_RESULT).payload()).u16());BaselineTest.send(a,START_MATCH,new byte[0]);assertEquals(Protocol.Error.NOT_READY.ordinal(),new Reader(BaselineTest.waitFor(a,ACTION_RESULT).payload()).u16());BaselineTest.send(b,SET_READY,new byte[]{2});assertEquals(Protocol.Error.INVALID_REQUEST.ordinal(),new Reader(BaselineTest.waitFor(b,ACTION_RESULT).payload()).u16());BaselineTest.send(a,LEAVE_ROOM,new byte[0]);BaselineTest.waitFor(a,ACTION_RESULT);Reader state=new Reader(BaselineTest.waitFor(b,ROOM_STATE).payload());state.u32();state.str(48);state.u8();assertEquals(1,state.u8());try(Socket malformed=new Socket("127.0.0.1",s.tcp.getLocalPort())){malformed.setSoTimeout(1000);malformed.getOutputStream().write(new byte[12]);assertEquals(-1,malformed.getInputStream().read());}BaselineTest.send(b,ROOM_LIST,new byte[0]);assertEquals(0,new Reader(BaselineTest.waitFor(b,ROOM_LIST_RESULT).payload()).u16());}}
 @Test void lostAckAndResync()throws Exception{try(Server s=server();Socket a=new Socket("127.0.0.1",s.tcp.getLocalPort());Socket b=new Socket("127.0.0.1",s.tcp.getLocalPort())){BaselineTest.auth(a,"alpha");BaselineTest.auth(b,"bravo");BaselineTest.send(a,CREATE_ROOM,new Writer().str("test").done());BaselineTest.waitFor(a,ACTION_RESULT);int id=new Reader(BaselineTest.waitFor(a,ROOM_STATE).payload()).u32();Room r=s.rooms.get(id);BaselineTest.send(b,JOIN_ROOM,new Writer().u32(id).done());BaselineTest.waitFor(b,ACTION_RESULT);var done=new java.util.concurrent.CompletableFuture<Void>();r.enqueue(()->{for(var m:r.members.values()){m.cache.put(1,new World(null,0).encode());m.ack=0;}var first=r.members.values().iterator().next();r.ack(first.session,123);assertEquals(0,first.ack);r.ack(first.session,1);assertEquals(1,first.ack);r.ack(first.session,0);assertEquals(1,first.ack);r.resync(first.session);assertTrue(first.forceFull);done.complete(null);});done.get(2,java.util.concurrent.TimeUnit.SECONDS);}}
 @Test void authExceptionRequiresBenchmarkAndExplicitAddress()throws Exception{try(Server s=server()){InetAddress remote=InetAddress.getByName("192.0.2.25");assertTrue(s.benchmarkAuthExempt(InetAddress.getLoopbackAddress()));assertFalse(s.benchmarkAuthExempt(remote));s.cfg.p.setProperty("benchmark.auth.allowed.ips","192.0.2.25");assertTrue(s.benchmarkAuthExempt(remote));s.cfg.p.setProperty("benchmark","false");assertFalse(s.benchmarkAuthExempt(remote));assertFalse(s.benchmarkAuthExempt(InetAddress.getLoopbackAddress()));}}
 @Test void busyPortFailsBeforeOpeningDatabase()throws Exception{try(Server s=server()){Config duplicate=new Config(tmp.resolve("server.properties"));duplicate.p.setProperty("tcp.port",""+s.tcp.getLocalPort());Path unused=tmp.resolve("never-opened.db");duplicate.p.setProperty("database.path",unused.toString());assertThrows(BindException.class,()->new Server(duplicate));assertFalse(Files.exists(unused));}}
 @Test void closeDuringPendingLoginDoesNotReserveAccount()throws Exception{var gate=new java.util.concurrent.CountDownLatch(1);try(Server s=server()){var a=s.db.submit(()->s.db.register("closing","password123")).get();s.db.worker.execute(()->{try{gate.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}});Socket client=new Socket("127.0.0.1",s.tcp.getLocalPort());BaselineTest.send(client,LOGIN,new Writer().str("closing").str("password123").done());long until=System.nanoTime()+2_000_000_000L;while(s.connections.stream().noneMatch(c->c.authBusy)&&System.nanoTime()<until)Thread.sleep(5);client.close();while(!s.connections.isEmpty()&&System.nanoTime()<until)Thread.sleep(5);gate.countDown();s.db.submit(()->null).get();assertFalse(s.accounts.containsKey(a.id()));try(Socket next=new Socket("127.0.0.1",s.tcp.getLocalPort())){next.setSoTimeout(5000);BaselineTest.send(next,LOGIN,new Writer().str("closing").str("password123").done());assertEquals(0,new Reader(BaselineTest.waitFor(next,LOGIN_RESULT).payload()).u16());}}finally{gate.countDown();}}
 @Test void closedCreatorDoesNotLeaveEmptyRoom()throws Exception{try(Server s=server()){Room room=new Room(s,99,"empty");s.rooms.put(99,room);var session=s.new Session(new Socket());session.room=room;session.open=false;room.join(session,1);assertFalse(s.rooms.containsKey(99));assertFalse(room.alive);}}
 @Test void invalidPasswordThenTwoLocalAccountsRespectProductionAuthLimit()throws Exception{try(Server s=server();Socket a=new Socket("127.0.0.1",s.tcp.getLocalPort());Socket b=new Socket("127.0.0.1",s.tcp.getLocalPort());Socket extra=new Socket("127.0.0.1",s.tcp.getLocalPort())){
  s.cfg.p.setProperty("benchmark","false");a.setSoTimeout(5000);b.setSoTimeout(5000);extra.setSoTimeout(5000);
  BaselineTest.send(a,REGISTER,new Writer().str("test1").str("short").done());assertEquals(Protocol.Error.INVALID_REQUEST.ordinal(),new Reader(BaselineTest.waitFor(a,REGISTER_RESULT).payload()).u16());
  BaselineTest.auth(a,"test1");BaselineTest.auth(b,"test2");
  BaselineTest.send(extra,REGISTER,new Writer().str("test3").str("password123").done());assertEquals(Protocol.Error.RATE_LIMITED.ordinal(),new Reader(BaselineTest.waitFor(extra,REGISTER_RESULT).payload()).u16());
  assertEquals(2,s.accounts.size());
 }}
}
